from schema import T,S,E,Q,X
TOPICS=[]
def C(id,title,level,parts,lines,extra,gist):
    # The dialogue is revisited as explained examples: context first, then noticing.
    examples=[E(*x) for x in lines+extra]
    sections=[S(h,p,examples[i*2:i*2+2]) for i,(h,p) in enumerate(parts)]
    t=T(id,title,level,'Inglés en uso',title,sections,[],[])
    t['scene']=[{'speaker':i%2,'en':x[0],'es':x[1]} for i,x in enumerate(lines)]
    t['gist']={'prompt':gist[0],'es':gist[1],'answer':gist[2],'options':gist[2:5],'evidence':gist[5]}
    # Two contextual checks: retrieve a meaning and recognise the explained contrasting form.
    for i in [1,5]:
        x=examples[i];others=[e['en'] for j,e in enumerate(examples) if j!=i][:2]
        t['questions'].append(Q('¿Qué frase expresa «'+x['es']+'»?',x['en'],others[0],others[1],x['why']))
    TOPICS.append(t)
C('possession','De quién es y cuál señalas','a1',[
('My bag / mine','My, your, his, her, its, our y their van delante del nombre. Mine, yours, his, hers, ours y theirs sustituyen al grupo completo. El posesivo depende de quien posee: her brother significa el hermano de ella, aunque brother sea masculino.'),
('Una persona concreta: ’s','Un poseedor singular lleva ’s; un plural terminado en s lleva solo apóstrofo. Los plurales irregulares llevan ’s: children’s. Whose pregunta por posesión; who’s contrae who is o who has. No significan lo mismo.'),
('This, that, these, those','This/these suelen acercar una referencia; that/those, alejarla. This/that son singulares; these/those, plurales. La distancia puede ser física o del discurso: That was fun se refiere a una experiencia ya pasada.')],
[('Is this your bag?','¿Esta es tu bolsa?','Your acompaña al nombre bag; this señala una bolsa cercana.'),('No, mine is blue.','No, la mía es azul.','Mine sustituye a my bag.'),('Then whose bag is it?','Entonces, ¿de quién es?','Whose pregunta por el dueño.'),("It is Mia’s. Those shoes are hers too.",'Es de Mia. Esos zapatos también son suyos.','Mia’s identifica a la persona; hers evita repetir her shoes.')],
[('This chair is free. Those chairs are taken.','Esta silla está libre. Aquellas están ocupadas.','This es singular; those es plural.'),("The students’ bags are here.",'Las bolsas de los estudiantes están aquí.','Students’ indica varios estudiantes; student’s indicaría uno.')],
['What colour is the second speaker’s bag?','¿De qué color es la bolsa de la segunda persona?','Blue','Red','Black',1])
C('adjectives','Describir personas y cosas','a1',[
('Adjetivos y posiciones','El adjetivo suele ir antes del sustantivo o después de be, seem, look y feel. No recibe plural ni género. What is he like? pide una descripción; what does he look like? se centra en apariencia; what does he like? pregunta gustos.'),
('Orden y precisión','Con varios adjetivos, la opinión suele preceder a tamaño, edad, color y material. No hace falta acumularlos: una descripción útil selecciona rasgos relevantes. Hair suele ser incontable cuando describe toda la cabellera.'),
('Bored / boring','En parejas como interested/interesting, -ed describe la reacción experimentada y -ing lo que la provoca. No equivale a persona frente a cosa: una persona puede ser interesting y un animal puede estar frightened.')],
[('What is your neighbour like?','¿Cómo es tu vecino?','Is…like pide una descripción.'),('He is friendly, but quite quiet.','Es amable, pero bastante callado.','Be conecta con adjetivos; no se añade -s a friendly.'),('Is he interested in music?','¿Le interesa la música?','Interested describe su reacción.'),('Yes. He has an amazing collection.','Sí. Tiene una colección increíble.','Amazing expresa el efecto de la colección.')],
[('I am bored. This game is boring.','Estoy aburrido. Este juego es aburrido.','Bored es mi reacción; boring describe el efecto del juego.'),('She bought a lovely small wooden table.','Compró una bonita mesa pequeña de madera.','Opinión, tamaño y material aparecen antes de table.')],
['What is the neighbour like?','¿Cómo es el vecino?','Friendly and quiet','Angry and loud','Tired and worried',1])
C('have','Have, have got y expresiones cotidianas','a1',[
('Posesión y relaciones','Have/has expresa posesión, relaciones y características. Does/doesn’t lleva la tercera persona y el verbo principal vuelve a have. Have no se añade detrás de am para formar una afirmación: I have a bike ya tiene verbo.'),
('Have got','Have got es frecuente para posesión presente, especialmente en inglés británico. Preguntas y negativas usan have/has: Have you got…? / I haven’t got… El pasado de posesión suele expresarse con had.'),
('Actividad o estado','Have breakfast, have a shower y have a rest nombran actividades y admiten continuo. Have got no sustituye a have en cualquier expresión. La edad y sensaciones como frío o hambre se construyen con be: I am cold, I am hungry.')],
[('Do you have a charger?','¿Tienes un cargador?','Do forma la pregunta con have.'),("Yes, I have got one in my bag.",'Sí, tengo uno en mi bolsa.','Have got expresa posesión; one retoma charger.'),('Have you got a minute?','¿Tienes un minuto?','Have se coloca antes del sujeto en esta construcción.'),("Sorry, I am having lunch. Can I help you later?",'Perdón, estoy almorzando. ¿Puedo ayudarte después?','Have lunch es actividad; por eso admite continuo.')],
[('She has two brothers. Does she have a sister?','Tiene dos hermanos. ¿Tiene una hermana?','Has en afirmación; does + have en pregunta.'),('I am hungry, but I do not have any food.','Tengo hambre, pero no tengo comida.','Be + hungry describe estado; have + food, posesión.')],
['Why can’t the person help immediately?','¿Por qué no puede ayudar inmediatamente?','They are having lunch.','They have no charger.','They are at work.',3])
C('existence','Hay: there is y there are','a1',[
('Presentar lo que existe','There is presenta un singular o incontable; there are, un plural. Este there introduce existencia y no significa necesariamente allí. It/they retoman una cosa ya identificada para describirla.'),
('Preguntar y negar','La pregunta invierte be: Is there…? / Are there…? Any es frecuente en preguntas y negativas; some, en afirmaciones. En escritura regular, usa there are con plurales aunque oigas there’s + plural en habla informal.'),
('Otros momentos','Cambia be para expresar tiempo: there was/were, there will be, there has/have been. Había no se traduce con had si solamente expresa existencia. Have necesita un poseedor o su construcción verbal propia.')],
[('Is there a café near here?','¿Hay una cafetería cerca?','Se pregunta por existencia de un singular.'),('Yes, there is one next to the bank.','Sí, hay una junto al banco.','One sustituye a café.'),('Are there any tables outside?','¿Hay mesas afuera?','Tables es plural: are.'),('Yes, but they are wet.','Sí, pero están mojadas.','They retoma las mesas ya mencionadas.')],
[('There is a lamp in the room. It is old.','Hay una lámpara en la habitación. Es vieja.','Primero presentas, después describes con it.'),('There were two people at the door.','Había dos personas en la puerta.','Were expresa existencia plural pasada.')],
['Are the tables dry?','¿Están secas las mesas?','No, they are wet.','Yes, they are dry.','There are no tables.',3])
C('place','Ubicación, movimiento e indicaciones','a1',[
('In / on / at','At presenta un punto o lugar de actividad; in, un espacio interior; on, una superficie y ciertos transportes. La preposición depende de cómo se presenta el lugar, no de traducir siempre en por la misma palabra.'),
('Destino y recorrido','To indica destino; into, entrada; out of, salida; across, cruce; along, seguir una línea. Go home no lleva to. By bus describe medio de transporte; on the bus expresa ubicación.'),
('Dar indicaciones','El imperativo utiliza la base y normalmente omite you. Don’t + base expresa una instrucción negativa. At the bank fija dónde girar; next to y opposite permiten verificar referencias distintas.')],
[('I am at the station. Where are you?','Estoy en la estación. ¿Dónde estás?','At presenta la estación como punto de encuentro.'),('I am in the café opposite the station.','Estoy en la cafetería enfrente de la estación.','In sitúa dentro; opposite, enfrente.'),('How do I get there?','¿Cómo llego?','Get there pregunta cómo alcanzar el lugar.'),('Cross the road and turn right.','Cruza la calle y gira a la derecha.','Dos imperativos conectan los pasos.')],
[('Walk along the river, then across the bridge.','Camina junto al río y luego cruza el puente.','Along sigue un recorrido; across cruza.'),('The keys are in the bag, on the chair.','Las llaves están en la bolsa, sobre la silla.','Interior y superficie requieren preposiciones diferentes.')],
['Where is the second speaker?','¿Dónde está la segunda persona?','In the café','On the train','In the bank',1])
C('time','Hora, fechas y duración','a1',[
('La hora','Nine thirty y half past nine expresan 9:30; quarter to ten, 9:45. A.m./p.m. o morning/evening aclaran el momento. How long pregunta duración; when pregunta cuándo; how often, frecuencia.'),
('At / on / in','At acompaña horas y expresiones como at night; on, días y fechas; in, meses, años y periodos amplios. Next, last, this y every suelen ir sin preposición. Escribir el mes evita la ambigüedad entre formatos numéricos de fecha.'),
('For / since / until / by','For introduce duración; since, punto inicial con un tiempo verbal adecuado. Until expresa continuidad hasta un límite; by, plazo de finalización. During se construye con un periodo nominal, no normalmente con una duración contada como two hours.')],
[('When is your appointment?','¿Cuándo es tu cita?','When pide el momento.'),('On Friday, at half past nine.','El viernes, a las nueve y media.','On introduce día y at introduce hora.'),('How long does it take?','¿Cuánto dura?','How long pide duración, no hora de inicio.'),('About twenty minutes.','Unos veinte minutos.','About marca una aproximación.')],
[('Send it by Friday. I will stay here until Friday.','Envíalo a más tardar el viernes. Me quedaré hasta el viernes.','By marca plazo; until, continuidad.'),('I waited for two hours during the afternoon.','Esperé dos horas durante la tarde.','For mide duración; during sitúa el periodo.')],
['When is the appointment?','¿Cuándo es la cita?','Friday at half past nine','Thursday at nine','Friday at half past eight',1])
C('quantity','Contar, medir y expresar suficiencia','a1',[
('Contable o incontable','Un contable admite a/an y números: an egg, two eggs. Rice, advice e information suelen ser incontables en estos sentidos; para unidades usa a bag of rice o a piece of advice. El mismo nombre puede cambiar de uso: two coffees suele contar pedidos o tazas.'),
('Some / any / much / many','Some es frecuente en afirmaciones y ofrecimientos; any, en preguntas y negativas. How many acompaña plurales contables; how much, incontables. A lot of sirve para ambos. No se dice an advice para un consejo en el uso ordinario.'),
('Poco, demasiado y suficiente','A few/a little presenta una cantidad disponible; few/little destaca escasez. Enough va antes de nombres y después de adjetivos. Too expresa exceso para una finalidad, no solamente intensidad: very hot puede ser tolerable; too hot implica un problema.')],
[('Do we have enough food?','¿Tenemos suficiente comida?','Enough precede al nombre food.'),('We have some rice, but only a few eggs.','Tenemos arroz, pero solo unos pocos huevos.','Rice es incontable y eggs contable plural.'),('How much rice is there?','¿Cuánto arroz hay?','How much pregunta cantidad incontable.'),('A little. We need another bag.','Un poco. Necesitamos otra bolsa.','A little retoma rice; bag aporta unidad contable.')],
[('The room is big enough, but there are too many chairs.','La sala es suficientemente grande, pero hay demasiadas sillas.','Enough sigue al adjetivo; too many precede a un plural.'),('We have a little time, so we can talk.','Tenemos algo de tiempo, así que podemos hablar.','A little pone el foco en lo que sí queda.')],
['What do they need?','¿Qué necesitan?','Another bag of rice','More plates','A table',3])
C('comparisons','Comparar opciones y diferencias','a2',[
('Dos opciones','Muchos adjetivos cortos usan -er; los largos suelen usar more/less. Than introduce la referencia comparada. Good/bad forman better/worse; big forma bigger y easy, easier. No se duplican more y -er en more cheaper.'),
('Igualdad y superlativos','As + adjetivo + as expresa igualdad; not as…as, menor grado. El superlativo selecciona dentro de un grupo: the biggest / the most useful. Un posesivo puede sustituir a the: my best friend.'),
('Medir la diferencia','Much/far/a lot intensifican comparativos; slightly/a bit expresan diferencias pequeñas. Very no suele modificar better directamente. The more…the more relaciona cambios; esa construcción no demuestra una causa por sí sola.')],
[('Which room should we book?','¿Qué habitación reservamos?','Which pide elegir dentro de opciones.'),('This one is cheaper, but that one is much quieter.','Esta es más barata, pero aquella es mucho más silenciosa.','Much intensifica quieter.'),('Is the cheaper one as big?','¿La más barata es igual de grande?','As big pregunta igualdad de tamaño.'),('Almost. The cheaper room is the best option for our budget.','Casi. La más barata es la mejor opción para nuestro presupuesto.','Best evalúa según un criterio explícito: presupuesto.')],
[('This route is slightly faster than the other one.','Esta ruta es algo más rápida que la otra.','Slightly indica una diferencia pequeña.'),('The earlier we book, the less we pay.','Cuanto antes reservamos, menos pagamos.','Las dos comparaciones avanzan juntas.')],
['Which room suits their budget?','¿Qué habitación se ajusta al presupuesto?','The cheaper one','The quieter one, definitely','Neither is available',3])
C('other-pronouns','One, someone, myself y each other','a2',[
('Evitar repetir el nombre','One sustituye un contable singular y ones un plural. No se usa como sustituto normal de incontables: para agua puedes decir some, no a one. El antecedente debe ser claro para que la otra persona sepa qué objeto eliges.'),
('Alguien, algo y nadie','Someone/something introducen existencia; anyone/anything aparecen en preguntas/negativas y pueden expresar libre elección. Nothing/nobody ya son negativos y no necesitan not en la construcción estándar. Everybody lleva verbo singular, aunque se retome con they.'),
('La misma persona o personas diferentes','Myself/yourself/etc. indican que sujeto y objeto coinciden o añaden énfasis. By myself significa sin compañía o ayuda. Each other expresa reciprocidad. No se añaden reflexivos automáticamente donde el español dice me ducho.')],
[('Do you want the red cups or the blue ones?','¿Quieres las tazas rojas o las azules?','Ones sustituye cups.'),('The blue ones. Is there anything else to carry?','Las azules. ¿Hay algo más que llevar?','Anything else pregunta por otra cosa.'),('No, I can carry the box myself.','No, puedo llevar la caja yo mismo.','Myself enfatiza que lo haré personalmente.'),('Let us help each other with the chairs.','Ayudémonos con las sillas.','Each other expresa ayuda recíproca.')],
[('I did not see anyone. Nobody was there.','No vi a nadie. No había nadie.','Dos maneras de expresar ausencia sin doble negación estándar.'),('She introduced herself.','Ella se presentó.','La persona que presenta es la presentada.')],
['Which cups are chosen?','¿Qué tazas eligen?','The blue ones','The red ones','No cups',1])
C('frequency','Rutinas, frecuencia y modo','a1',[
('Posición del adverbio','Always, usually y never suelen ir antes del verbo principal, después de be o después del primer auxiliar. Never ya expresa negación. No siempre y nunca no son equivalentes: not always deja ocasiones en que sí ocurre.'),
('Repeticiones y duración','Once, twice y three times cuentan repeticiones. Every day indica cuándo; everyday es un adjetivo: my everyday bag. How often pregunta frecuencia; how long pregunta duración.'),
('Cómo se realiza la acción','Muchos adverbios de modo añaden -ly; good pasa a well. Fast y hard pueden ser adverbios sin -ly. Hardly significa apenas. El modo suele ir después del verbo y su objeto: explain the problem clearly.')],
[('How often do you cook?','¿Con qué frecuencia cocinas?','How often pide repeticiones.'),('Usually three times a week.','Normalmente tres veces por semana.','Three times cuenta las ocasiones.'),('Are you always busy on Mondays?','¿Siempre estás ocupado los lunes?','Always va después de be.'),('Not always. Sometimes I am free after six.','No siempre. A veces estoy libre después de las seis.','Not always deja excepciones.')],
[('She usually walks to school. She is usually early.','Suele ir andando a la escuela. Suele llegar pronto.','Usually precede a walks pero sigue a is.'),('He works hard. He hardly rests.','Trabaja mucho. Apenas descansa.','Hard y hardly tienen significados distintos.')],
['How often does the person usually cook?','¿Con qué frecuencia suele cocinar?','Three times a week','Every day','Once a month',1])
C('present-simple','Rutinas, estados y hechos','a1',[
('Lo habitual','El presente simple presenta hábitos, estados y hechos considerados generales. No implica que la acción ocurra al hablar. What do you do? suele preguntar profesión; what are you doing? pide la actividad actual. El significado decide el tiempo, no una sola palabra clave.'),
('Una marca de tercera persona','He/she/it y nombres singulares llevan normalmente -s: works; -es tras ciertos finales: watches; consonante + y cambia a -ies: studies. Have cambia a has. Does/doesn’t ya lleva la marca de persona y el principal vuelve a su base.'),
('Horarios y preguntas','El presente simple puede referirse al futuro en horarios establecidos. Las preguntas informativas añaden where/when/why/how antes del auxiliar. Be sigue su propio sistema: Is she ready?, sin does.')],
[('What do you do?','¿A qué te dedicas?','Esta pregunta suele pedir ocupación.'),('I work in a bookshop.','Trabajo en una librería.','Una situación laboral habitual.'),('Does it open on Sundays?','¿Abre los domingos?','Does ya lleva tercera persona; open queda en base.'),('No, it does not. We close on Sundays.','No. Cerramos los domingos.','Do permite responder sin repetir open.')],
[('Mia studies here. Does Leo study here too?','Mia estudia aquí. ¿Leo también estudia aquí?','Studies en afirmación; does + study en pregunta.'),('The class starts at nine tomorrow.','La clase empieza mañana a las nueve.','Un horario fijo admite presente simple para futuro.')],
['Does the bookshop open on Sundays?','¿La librería abre los domingos?','No, it closes.','Yes, every Sunday.','Only on Sundays.',3])
C('present-continuous','Ahora, esta semana y situaciones temporales','a1',[
('Dentro de la actividad','Am/is/are + -ing presenta una acción en desarrollo o una situación temporal alrededor de ahora. No tiene que suceder cada segundo: leer una novela este mes es un proceso temporal. El simple presenta la rutina; el continuo, el episodio.'),
('Forma, negación y pregunta','Be cambia con el sujeto; el principal conserva -ing. Las preguntas invierten be y sujeto; not niega. Make→making pierde e, run→running duplica consonante y lie→lying cambia ie a y. No se añade do al continuo.'),
('Estados y significados','Know, need y believe normalmente usan simple en sus sentidos de estado. Algunos verbos cambian de uso: I think expresa opinión; I am thinking about expresa reflexión. Have como actividad admite continuo; como posesión ordinaria, normalmente no.')],
[('Do you work from home?','¿Trabajas desde casa?','Se pregunta por rutina.'),('Usually, yes. But this week I am working at the office.','Normalmente sí. Esta semana trabajo en la oficina.','El continuo presenta una excepción temporal.'),('What are you doing now?','¿Qué haces ahora?','Are se coloca antes del sujeto.'),('I am waiting for a meeting to start.','Espero que empiece una reunión.','La espera está en desarrollo.')],
[('I live in Lima. I am staying in Cusco this week.','Vivo en Lima. Esta semana me alojo en Cusco.','Residencia habitual frente a alojamiento temporal.'),('I think it is useful. I am thinking about buying it.','Creo que es útil. Estoy pensando en comprarlo.','Think cambia de sentido entre opinión y proceso mental.')],
['Where is the person working this week?','¿Dónde trabaja esta semana?','At the office','At home','At a bookshop',1])
C('past-simple','Hechos terminados y pasado de be','a1',[
('Un periodo pasado','El pasado simple presenta hechos o estados dentro de un periodo pasado terminado. Yesterday o last year pueden indicarlo, pero el contexto también basta. Be cambia a was/were; los otros verbos tienen forma regular o irregular.'),
('Did lleva el pasado','Los regulares añaden -ed, con cambios como study→studied y stop→stopped. Los irregulares usan una forma propia: go→went. En preguntas y negativas, did/didn’t + base: Did she go? Con was/were no se añade did.'),
('Secuencia y sonido','Varias acciones en simple suelen avanzar una narración. Before, after y then aclaran el orden. -ed se pronuncia /t/, /d/ o /ɪd/ según el sonido previo; no siempre se añade una sílaba. El pasado simple no necesita have.')],
[('How was your weekend?','¿Qué tal tu fin de semana?','Was pregunta por una experiencia pasada.'),('It was great. I visited my cousins.','Muy bien. Visité a mis primos.','Was describe; visited cuenta la acción.'),('Did you stay overnight?','¿Te quedaste a dormir?','Did + stay, sin -ed.'),('No, I came home on Saturday evening.','No, regresé a casa el sábado por la tarde.','Came es pasado irregular de come.')],
[('Were they tired? Yes, they were.','¿Estaban cansados? Sí.','La pregunta con be invierte were.'),('I opened the door, took off my coat and sat down.','Abrí la puerta, me quité el abrigo y me senté.','Tres acciones hacen avanzar la historia.')],
['When did the person come home?','¿Cuándo volvió a casa?','Saturday evening','Sunday morning','Monday afternoon',3])
C('past-continuous','Lo que estaba ocurriendo','a2',[
('Un pasado visto desde dentro','Was/were + -ing muestra una acción en curso en un momento pasado. No afirma cuándo comenzó ni si terminó. I cooked presenta un hecho completo; I was cooking muestra su desarrollo. I/he/she/it usan was; you/we/they, were.'),
('Fondo y acontecimiento','El continuo suele crear el fondo; el simple introduce un acontecimiento que ocurre durante él. When y while no imponen automáticamente un tiempo: interesa si hablamos de un punto o una actividad en curso.'),
('Acciones paralelas','Dos continuos pueden describir actividades simultáneas. Los estados de fondo suelen usar simple: the room was dark, she knew. No es necesario convertir todos los verbos de una historia en continuo.')],
[('Why did you miss my call?','¿Por qué no contestaste mi llamada?','La pregunta delimita un hecho pasado.'),('I was cycling home when you called.','Iba en bicicleta a casa cuando llamaste.','Cycling es el fondo; called, el evento.'),('Was it raining?','¿Estaba lloviendo?','Was se invierte con it.'),('Yes, and the road was getting slippery.','Sí, y la carretera se estaba poniendo resbaladiza.','Getting describe un cambio en desarrollo.')],
[('While I was reading, she was writing.','Mientras yo leía, ella escribía.','Dos actividades simultáneas.'),('When I arrived, they were eating.','Cuando llegué, estaban comiendo.','La comida ya estaba en curso al llegar.')],
['Why was the call missed?','¿Por qué no contestó?','The person was cycling.','The person was sleeping.','The phone was lost.',1])
C('past-perfect','Antes de otro momento pasado','b1',[
('Anterioridad, no antigüedad','Had + participio mira hacia atrás desde un punto pasado. No significa simplemente que algo sea muy antiguo. La referencia puede aparecer en la oración o estar clara por la narración. When I arrived, they had left sitúa primero la salida.'),
('Participio y perspectiva','Had se usa con todos los sujetos; hadn’t niega y Had you…? pregunta. Went/gone y saw/seen distinguen pasado y participio. La contracción ’d puede ser had o would: lo que sigue ayuda a distinguirlas.'),
('Cuándo basta el simple','After/before pueden dejar claro el orden sin perfecto. Una vez establecido el marco anterior, la narración puede continuar en simple cuando la secuencia sea evidente. Evita añadir had a todas las frases sin cambiar de punto de vista.')],
[('Why did you walk home?','¿Por qué volviste andando?','La pregunta pide una razón pasada.'),('The last bus had already left when I arrived.','El último autobús ya había salido cuando llegué.','La salida es anterior a la llegada.'),('Had you checked the timetable?','¿Habías consultado el horario?','Had se invierte en la pregunta.'),('Yes, but the timetable had changed.','Sí, pero el horario había cambiado.','El cambio anterior explica el problema.')],
[('She had not eaten, so she was hungry.','No había comido, así que tenía hambre.','Una situación anterior explica el estado pasado.'),('After she finished work, she went home.','Después de terminar el trabajo, se fue a casa.','After ya deja claro el orden de los hechos.')],
['What happened before the person arrived?','¿Qué ocurrió antes de su llegada?','The last bus had left.','The bus broke down.','The timetable was printed.',1])
C('present-perfect','El pasado conectado con ahora','a2',[
('Experiencia y resultado','Have/has + participio conecta algo anterior con ahora: experiencia hasta hoy, resultado vigente o periodo todavía abierto. Normalmente no lleva yesterday o una fecha pasada terminada. Hay diferencias de uso entre variedades británicas y estadounidenses.'),
('Ever, never, already y yet','Ever pregunta por alguna ocasión; never indica ninguna. Just suele indicar muy reciente; already, antes de lo esperado; yet pregunta o niega hasta ahora. Been to suele implicar visita con regreso; gone to suele indicar que la persona sigue fuera.'),
('Duración y seguimiento','For mide duración; since da el inicio. How long have you…? pregunta por una situación que continúa. Al pedir detalles de una experiencia terminada suele pasarse a simple: Have you been there? When did you go? Know, como estado, prefiere perfecto simple.')],
[('Have you ever been to Arequipa?','¿Has estado alguna vez en Arequipa?','Se pregunta experiencia sin fecha concreta.'),('Yes, I have. I went there last year.','Sí. Fui el año pasado.','El detalle fechado cambia a pasado simple.'),('Have you booked another trip yet?','¿Ya has reservado otro viaje?','Yet pregunta hasta ahora.'),('Not yet. I have been busy since Monday.','Todavía no. Estoy ocupado desde el lunes.','Since marca el comienzo de la situación.')],
[('I have lost my keys. I cannot get in.','He perdido las llaves. No puedo entrar.','El resultado afecta a la situación presente.'),('I have known her for five years.','La conozco desde hace cinco años.','Know es estado; for expresa duración.')],
['When did the person go to Arequipa?','¿Cuándo fue a Arequipa?','Last year','Last Monday','Not yet',1])
C('perfect-continuous','Actividad y duración hasta un momento','b1',[
('La actividad y su huella','Have/has been + -ing destaca actividad reciente o duración hasta ahora. La acción puede continuar o haber terminado hace poco; no se puede deducir solo por el tiempo verbal que siga ocurriendo. Un resultado visible puede explicar por qué se menciona.'),
('Proceso frente a cantidad','El perfecto simple suele destacar resultados completados; el continuo, proceso y duración. I have written three emails cuenta resultados; I have been writing all morning destaca actividad. Live/work admiten ambos en ciertos contextos; know normalmente usa simple.'),
('Hasta un punto pasado','Had been + -ing traslada la duración a un momento pasado. Puede explicar cansancio o una situación de entonces. Se diferencia de had done, que pone el foco en resultado/anterioridad más que en desarrollo.')],
[('Your shoes are muddy. What have you been doing?','Tus zapatos están embarrados. ¿Qué has estado haciendo?','La huella visible motiva la pregunta.'),('I have been working in the garden.','He estado trabajando en el jardín.','Se destaca la actividad reciente.'),('Have you planted the flowers?','¿Has plantado las flores?','El perfecto simple pregunta resultado.'),('Yes, I have planted ten. I have two left.','Sí, he plantado diez. Me quedan dos.','Ten cuenta resultados completados.')],
[('I have written three emails. I have been writing all morning.','He escrito tres correos. Llevo toda la mañana escribiendo.','Cantidad frente a proceso.'),('She was tired because she had been driving all night.','Estaba cansada porque había conducido toda la noche.','La actividad anterior explica un estado pasado.')],
['How many flowers are already planted?','¿Cuántas flores ya están plantadas?','Ten','Two','Twelve',3])
C('future','Intenciones, decisiones y acuerdos','a2',[
('Going to','Be going to + base expresa intención previa o predicción con evidencia presente. Be cambia con el sujeto. Gonna puede aparecer al representar habla informal, pero no reemplaza go to para un movimiento literal.'),
('Will','Will + base sirve para decisiones tomadas al hablar, ofertas, promesas y muchas predicciones. Won’t es la negación. No todas las referencias futuras usan will: las formas seleccionan cómo se presenta el evento.'),
('Acuerdos, horarios y when','El presente continuo puede expresar un plan organizado; el simple, un horario fijo. En cláusulas temporales futuras con when/as soon as/before se utiliza normalmente presente: I will call when I arrive, sin will en la cláusula temporal.')],
[('What are you doing on Saturday?','¿Qué vas a hacer el sábado?','El continuo pregunta planes.'),('I am meeting Eva at ten. We are going to visit the museum.','He quedado con Eva a las diez. Vamos a visitar el museo.','Acuerdo con hora e intención de visita.'),('The tickets are cheaper online.','Los billetes son más baratos por internet.','La información provoca una decisión.'),('Really? I will book them now.','¿En serio? Los reservaré ahora.','Will expresa una decisión al hablar.')],
[('Look at that glass! It is going to fall.','¡Mira ese vaso! Se va a caer.','La predicción tiene evidencia presente.'),('I will call you when I arrive.','Te llamaré cuando llegue.','When I arrive usa presente con sentido futuro.')],
['What does the person decide to do now?','¿Qué decide hacer ahora?','Book the tickets online','Cancel the trip','Meet on Friday',3])
C('future-advanced','Estará ocurriendo o estará terminado','b2',[
('Will be doing','Will be + -ing presenta actividad en progreso en un momento futuro o un desarrollo esperado. Will you be using the car? puede consultar planes antes de pedir algo. El futuro continuo no afirma que la actividad estará terminada.'),
('Will have done','Will have + participio mira desde un punto futuro hacia un resultado ya completado para entonces. By marca límite de finalización, no necesariamente el instante exacto de la acción. Until marca continuidad y no sustituye a by en ese uso.'),
('Duración y condiciones','Will have been + -ing mide duración hasta un punto futuro. Probably, may y if delimitan previsiones. Una expectativa como should have finished by noon no garantiza que se cumplirá ni implica siempre una crítica.')],
[('Can we call you at eight?','¿Podemos llamarte a las ocho?','Se propone una hora.'),('I will be travelling then. Could you call at ten?','Estaré viajando. ¿Podrían llamar a las diez?','La actividad estará en curso a las ocho.'),('Will you have arrived by then?','¿Habrás llegado para entonces?','Se pregunta por finalización antes del punto futuro.'),('Yes, unless the train is delayed.','Sí, a menos que se retrase el tren.','Unless introduce una excepción al pronóstico.')],
[('By Friday, we will have checked every page.','Para el viernes habremos revisado todas las páginas.','La revisión estará completada para ese límite.'),('In June, I will have been working here for two years.','En junio llevaré dos años trabajando aquí.','Duración hasta un punto futuro.')],
['What will the person be doing at eight?','¿Qué estará haciendo a las ocho?','Travelling','Waiting at home','Having the call',1])
C('used-to','Antes y ahora: costumbre o familiaridad','b1',[
('Used to do','Used to + base presenta un hábito o estado pasado que contrasta con ahora. En preguntas y negativas con did se escribe normalmente use to. No expresa una única acción pasada ni una rutina actual.'),
('Would en recuerdos','Would + base puede narrar acciones repetidas en un marco pasado ya establecido. No suele reemplazar a used to para estados como own/live en esta función. El simple también puede expresar hábitos cuando el contexto marca repetición.'),
('Be/get used to','Be used to + nombre/-ing expresa familiaridad; get used to, el proceso de acostumbrarse. Aquí to es preposición y por eso precede a -ing. Be/get pueden cambiar de tiempo. No equivale a used to + base.')],
[('Do you like working at night?','¿Te gusta trabajar de noche?','Se pregunta por una preferencia.'),('I am used to it now, but it was hard at first.','Ahora estoy acostumbrado, pero al principio era difícil.','Be used to expresa familiaridad actual.'),('Did you use to work during the day?','¿Antes trabajabas de día?','Did + use to pregunta por un hábito pasado.'),('Yes. I used to start at eight.','Sí. Antes empezaba a las ocho.','Used to describe la rutina que cambió.')],
[('I used to live near the sea. Now I live inland.','Antes vivía cerca del mar. Ahora vivo en el interior.','Un estado anterior distinto al presente.'),('It took me a month to get used to the noise.','Tardé un mes en acostumbrarme al ruido.','Get used to destaca el cambio hacia la familiaridad.')],
['When did the person use to start work?','¿A qué hora empezaba antes?','At eight','At night','At six',3])
C('ability-permission','Poder, pedir permiso y ofrecer ayuda','a1',[
('Can y could','Can + verbo base expresa capacidad, posibilidad práctica o permiso. No lleva to ni cambia con he/she. Could describe capacidad general pasada o suaviza peticiones. Para un logro concreto pasado, was able to o managed to suelen ser más precisos que could afirmativo.'),
('Pedir y responder','Can I…? pide permiso; Can you…? pide a otra persona que actúe. Could you…? resulta más indirecto. La respuesta depende de la situación: Of course, Here you are o Sorry, I need it pueden ser más naturales que repetir el auxiliar.'),
('Permiso y límites','May I…? es una petición formal. Be allowed to permite hablar de permiso en otros tiempos. Must not prohíbe; cannot puede describir una prohibición o una imposibilidad. El contexto aclara cuál. No se combinan dos modales centrales: will be able to, no will can.')],
[('Can I use your phone?','¿Puedo usar tu teléfono?','Can I pide permiso.'),('Of course. Can you unlock it?','Claro. ¿Puedes desbloquearlo?','Can you pregunta si la otra persona puede hacerlo.'),('No. Could you help me?','No. ¿Podrías ayudarme?','Could you suaviza la petición.'),('Sure. Here you are.','Claro. Aquí tienes.','Se responde realizando la acción.')],
[('I could swim when I was six.','Sabía nadar cuando tenía seis años.','Capacidad general pasada.'),('We were allowed to leave early.','Nos permitieron salir temprano.','Allowed expresa permiso pasado, no capacidad física.')],
['What does the first speaker need?','¿Qué necesita la primera persona?','Help unlocking the phone','A new phone','Swimming lessons',2])
C('obligation','Reglas, necesidad y consejos','a2',[
('Must / have to','Must suele presentar una obligación desde quien habla; have to puede señalar una necesidad externa. Se solapan y no son una división absoluta. Have to admite pasado y futuro: had to, will have to. Must mantiene su forma.'),
('No debes / no hace falta','Must not o mustn’t prohíben. Do not have to indica ausencia de obligación: puedes hacerlo si quieres. Need to expresa necesidad; needn’t + base y do not need to son formas de decir que no es necesario.'),
('Consejos y consecuencias','Should + base recomienda sin convertir siempre el consejo en regla. Had better + base aconseja ante una posible consecuencia negativa; su negativo es had better not. Para una opinión amable puedes dar una razón y dejar espacio a la otra persona.')],
[('Do I have to print the ticket?','¿Tengo que imprimir el billete?','Have to pregunta por un requisito.'),('No, you can show it on your phone.','No, puedes mostrarlo en el teléfono.','No hay obligación de imprimir.'),('Can I bring my bike?','¿Puedo llevar mi bicicleta?','Se pregunta por permiso.'),('Yes, but you must not block the doors.','Sí, pero no debes bloquear las puertas.','Must not expresa una prohibición.')],
[('You do not have to come, but you are welcome.','No tienes que venir, pero eres bienvenido.','La actividad es opcional.'),('You should take a coat. It may get cold.','Deberías llevar abrigo. Puede hacer frío.','Consejo con una razón, no una prohibición.')],
['Is a paper ticket necessary?','¿Es necesario un billete de papel?','No','Yes, always','Only for bikes',1])
C('deduction','Decir qué crees que está pasando','b1',[
('Grados de seguridad','Must puede expresar una conclusión muy probable basada en pruebas. May, might y could presentan posibilidades. No tienen porcentajes fijos y universales. Una deducción no es una certeza demostrada: la evidencia puede ser incompleta.'),
('Una conclusión negativa','Cannot/can’t puede expresar que algo parece imposible. Must not suele interpretarse como prohibición, por lo que no es el opuesto habitual de must en deducciones. Para deducir una acción en curso usa modal + be + -ing.'),
('Explicar tu evidencia','Elige la forma por lo que sabes, no solo por la traducción de poder o deber. Maybe inicia una posibilidad como adverbio; may be contiene un modal y el verbo be. Probably suele ir antes del verbo principal o después de be.')],
[('Is Nora at home?','¿Nora está en casa?','Pregunta abierta sobre una situación actual.'),('She might be. Her bike is outside.','Puede que sí. Su bicicleta está fuera.','La bicicleta es una pista, no una prueba definitiva.'),('But her lights are off.','Pero sus luces están apagadas.','Se añade una pista que reduce la certeza.'),('She could be sleeping. Let us call later.','Puede estar durmiendo. Llamemos más tarde.','Could be + -ing ofrece una explicación posible.')],
[('You must be tired after that long walk.','Debes de estar cansado después de esa caminata.','Conclusión razonable a partir de una circunstancia.'),('That cannot be Sam. He is abroad.','Ese no puede ser Sam. Está en el extranjero.','Cannot niega una posibilidad con evidencia.')],
['Do the speakers know for sure where Nora is?','¿Saben con certeza dónde está Nora?','No, they are guessing','Yes, they saw her','Yes, she called them',3])
C('past-modals','Deducciones y decisiones del pasado','b2',[
('Modal + have + participio','Must have done propone una deducción sobre el pasado; might/may/could have done, una posibilidad. Cannot have done expresa incredulidad o imposibilidad según las pruebas. El participio conserva su forma, aunque el sujeto cambie.'),
('Consejos que llegan tarde','Should have done evalúa una acción pasada como deseable; should not have done critica una acción realizada. No cambia el pasado. Could have done también puede indicar una oportunidad no aprovechada: el contexto distingue oportunidad de deducción.'),
('Necesidad pasada','Needn’t have done indica que la acción se hizo, pero no hacía falta. Didn’t need to do expresa falta de necesidad; por sí solo no confirma si se hizo. Had to describe una obligación real pasada; must have no significa tuvo que en una deducción.')],
[('The café is closed. Did we get the time wrong?','La cafetería está cerrada. ¿Nos equivocamos de hora?','Se busca explicar un resultado presente.'),('They might have closed early today.','Puede que hayan cerrado temprano hoy.','Might have presenta una hipótesis sobre el pasado.'),('We should have checked before leaving.','Deberíamos haberlo comprobado antes de salir.','Evaluación de una acción que no se hizo.'),('Never mind. We could try the place next door.','No importa. Podríamos probar el local de al lado.','Could propone ahora una alternativa.')],
[('I needn’t have bought bread; we already had some.','No hacía falta que comprara pan; ya teníamos.','Compré pan y después advertí que era innecesario.'),('She must have missed the message.','Debe de haber pasado por alto el mensaje.','Deducción pasada; no expresa una obligación.')],
['What do they regret?','¿Qué lamentan?','Not checking the opening time','Buying bread','Calling the café',2])
C('verb-patterns','Qué forma sigue a cada verbo','a2',[
('Enjoy doing / want to do','Enjoy, avoid y finish suelen ir seguidos de -ing; want, decide y hope suelen llevar to + base. La elección depende del verbo, no de traducir literalmente el infinitivo español. Aprende el grupo con una situación: enjoy cooking, decide to leave.'),
('Finalidad y preposiciones','To + base puede expresar para qué haces algo. Después de una preposición normalmente aparece -ing: interested in learning, before leaving. To también puede ser preposición en look forward to y be used to; allí se usa nombre o -ing.'),
('Verbo + persona','Ask/tell/want someone to do incluyen a quien realiza la acción. Make/let someone do llevan base sin to en activa; help admite ambas variantes. En pasiva, made recupera to: was made to wait. Los modales centrales también llevan base.')],
[('What would you like to do this weekend?','¿Qué te gustaría hacer este fin de semana?','Would like va seguido de to + base.'),('I enjoy cooking. Shall we make dinner together?','Me gusta cocinar. ¿Preparamos la cena juntos?','Enjoy va seguido de -ing.'),('Great. I need to buy a few things first.','Genial. Primero necesito comprar algunas cosas.','Need to expresa una acción necesaria.'),('I can help you carry the bags.','Puedo ayudarte a llevar las bolsas.','Help someone carry usa base sin to.')],
[('I went outside to get some air.','Salí para tomar un poco de aire.','To get expresa finalidad.'),('She asked me to wait.','Me pidió que esperara.','Me es la persona que debe esperar.')],
['What activity do they plan?','¿Qué actividad planean?','Cooking together','Eating at a restaurant','Buying a car',1])
C('verb-meaning','Cuando -ing y to cambian el sentido','b2',[
('Remember / forget','Remember doing recuerda una experiencia anterior. Remember to do recuerda una tarea pendiente y la realiza. Forget to do implica que la tarea no se hizo por olvido. Never forget doing conserva el recuerdo de una experiencia.'),
('Stop / try','Stop doing interrumpe esa actividad. Stop to do interrumpe otra para realizar una nueva. Try to do destaca el esfuerzo por conseguirlo; try doing propone un experimento para ver si funciona. No son equivalentes automáticos.'),
('Regret / mean / go on','Regret doing lamenta algo pasado; regret to inform introduce una noticia desagradable formal. Mean to do significa tener intención; mean doing, implicar. Go on doing continúa lo mismo; go on to do pasa a una actividad posterior.')],
[('Did you remember to send the file?','¿Te acordaste de enviar el archivo?','La pregunta trata de una tarea que había que hacer.'),('Yes. I remember attaching it, too.','Sí. También recuerdo haberlo adjuntado.','Remember -ing recupera una acción anterior.'),('I cannot open it.','No puedo abrirlo.','Se presenta un problema actual.'),('Try downloading it first.','Prueba a descargarlo primero.','Try -ing propone una posible solución.')],
[('We stopped talking when the film started.','Dejamos de hablar cuando empezó la película.','Se detuvo la actividad de hablar.'),('We stopped to buy water.','Paramos para comprar agua.','Se interrumpió el viaje con esa finalidad.')],
['Why does the second speaker suggest downloading the file?','¿Por qué sugiere descargar el archivo?','To try to solve the opening problem','To remember a holiday','To delete the message',3])
C('phrasal-verbs','Verbos que funcionan en grupos','a2',[
('Verbo y partícula','En grupos como turn on o find out, la partícula contribuye al sentido. A veces es literal; otras, el significado no se deduce palabra por palabra. Aprende también el contexto, el objeto y si el verbo necesita complemento.'),
('Separar o no separar','Turn the light on y turn on the light son posibles. Con pronombre, turn it on, no turn on it. Look after a child no se separa: look after him. Un diccionario indica si un phrasal verb es separable y transitivo.'),
('Registro y precisión','Put off puede equivaler a postpone, pero no todos los verbos de varias palabras son informales ni todos tienen un sustituto exacto. Get on, get off y get into seleccionan contextos distintos. No basta con memorizar una traducción aislada.')],
[('Could you turn the music down?','¿Podrías bajar la música?','Turn down reduce el volumen.'),('Sure. Is that better?','Claro. ¿Así está mejor?','Respuesta natural a la petición.'),('Yes, thanks. I am looking after my little cousin.','Sí, gracias. Estoy cuidando a mi primito.','Look after significa cuidar y no se separa.'),('No problem. I can turn it off if he needs to sleep.','Sin problema. Puedo apagarla si necesita dormir.','El pronombre it va entre turn y off.')],
[('We put the meeting off until Friday.','Aplazamos la reunión hasta el viernes.','Put off admite el objeto entre verbo y partícula.'),('I found out that the shop had moved.','Me enteré de que la tienda se había trasladado.','Find out significa descubrir una información.')],
['Why does the first speaker want quieter music?','¿Por qué pide menos volumen?','They are caring for a child','They dislike all music','The shop has moved',2])
C('collocations','Combinaciones que suenan naturales','b1',[
('Las palabras tienen compañía','Make a decision, take a break y heavy rain son combinaciones habituales. No siempre coinciden con el verbo o adjetivo que elegirías en español. Aprender unidades como pay attention ayuda a producir frases completas con menos traducción palabra por palabra.'),
('Preposiciones y complementos','Depend on, interested in y responsible for incluyen una preposición habitual. Discuss something no necesita about; explain something to someone incluye to ante la persona. El patrón forma parte de aprender la palabra y puede cambiar según el significado.'),
('Precisión en contexto','Un sinónimo no siempre conserva la combinación: strong coffee es natural; powerful coffee normalmente no. En temas nuevos observa verbo, nombre y contexto juntos. Una traducción en el glosario es una ayuda, no una sustitución válida en toda frase.')],
[('Have you made a decision about the course?','¿Has tomado una decisión sobre el curso?','En inglés se combina make con decision.'),('Not yet. It depends on the timetable.','Todavía no. Depende del horario.','Depend se combina con on.'),('Let us take a break and look at it later.','Hagamos una pausa y lo vemos después.','Take a break es un grupo habitual.'),('Good idea. I need to pay more attention to the details.','Buena idea. Necesito prestar más atención a los detalles.','Pay attention to incluye la preposición.')],
[('Could you explain the problem to me?','¿Podrías explicarme el problema?','Explain + cosa + to + persona.'),('We discussed the price for an hour.','Hablamos del precio durante una hora.','Discuss lleva su objeto directamente.')],
['What affects the decision?','¿Qué influye en la decisión?','The timetable','The coffee','The weather',1])
C('word-formation','Familias de palabras','b2',[
('Función antes de forma','La posición orienta la clase de palabra: un nombre puede ir tras un artículo; un adjetivo describe un nombre; un adverbio puede modificar una acción. Decide qué función falta antes de añadir un sufijo. Success, successful, successfully y succeed no se intercambian.'),
('Prefijos y significado','Un-, in-/im-/il-/ir-, dis- y mis- cambian sentidos de maneras distintas: unhappy, impossible, dishonest, misunderstand. No se pueden aplicar libremente a cualquier palabra. Re- suele indicar repetición. Comprueba la familia y el significado real en contexto.'),
('Sufijos y cambios','-ness, -ment y -tion suelen formar nombres; -ful, -less y -ive, adjetivos; -ly suele formar adverbios, pero friendly es adjetivo. Hay cambios ortográficos y de acento: decide/decision, happy/happiness. No toda familia tiene todas las formas.')],
[('Was the presentation successful?','¿Tuvo éxito la presentación?','Successful describe la presentación.'),('Yes, but I was nervous at the beginning.','Sí, pero estaba nervioso al principio.','Nervous es un adjetivo de estado.'),('You explained the idea clearly.','Explicaste la idea con claridad.','Clearly modifica explained.'),('Thanks. Your encouragement really helped.','Gracias. Tu ánimo me ayudó mucho.','Encouragement es el nombre formado a partir de encourage.')],
[('Their decision was unexpected.','Su decisión fue inesperada.','Decision es nombre; unexpected, adjetivo con negación.'),('She completed the task successfully.','Completó la tarea con éxito.','Successfully describe cómo resultó la acción.')],
['What does clearly describe?','¿Qué describe clearly?','How the idea was explained','The number of ideas','The length of the talk',2])
C('adverbs','Matizar lo que afirmas','b2',[
('Alcance y posición','Only puede cambiar el foco según su posición: only Sam called excluye a otras personas; Sam only called puede contrastar llamar con visitar. Still expresa continuidad; already, anterioridad a lo esperado; yet suele aparecer al final en preguntas y negativas.'),
('Intensidad y grado','Very combina con muchos adjetivos graduables. Absolutely suele acompañar adjetivos extremos o no graduables. Quite cambia según el adjetivo y la variedad de inglés. Fairly, rather y pretty no son una escala matemática universal; tono y contexto influyen.'),
('Actitud y cautela','Apparently indica información que parece cierta o proviene de otra fuente; actually suele corregir una idea, no significa actualmente. Currently sí sitúa algo en el presente. Probably y possibly ayudan a no afirmar más de lo que permite la evidencia.')],
[('Have they finished the repairs yet?','¿Ya han terminado las reparaciones?','Yet pregunta por algo esperado.'),('Not yet. They are still working on the roof.','Todavía no. Siguen trabajando en el tejado.','Still destaca la continuidad.'),('Apparently, they will finish tomorrow.','Por lo visto, terminarán mañana.','Apparently deja ver que la información no es una certeza propia.'),('That would be great. The noise is rather distracting.','Sería estupendo. El ruido distrae bastante.','Rather matiza la intensidad de una valoración.')],
[('Only Mia saw the message.','Solo Mia vio el mensaje.','Only limita quién lo vio.'),('I currently work from home.','Actualmente trabajo desde casa.','Currently significa actualmente; actually suele ser en realidad.')],
['Are the repairs finished?','¿Han terminado las reparaciones?','No, work is continuing','Yes, since yesterday','No, they have not started',1])
C('emphasis','Énfasis y foco de la frase','b2',[
('La voz destaca información','Acentuar una palabra cambia el contraste implícito: I wanted the BLUE one sugiere otro color. El auxiliar do/does/did puede reforzar una afirmación: I did call. Después de did permanece la base, aunque la acción sea pasada.'),
('Reorganizar el foco','What I need is a break destaca la necesidad concreta. It was Mia who called destaca quién llamó. Estas construcciones organizan información conocida y nueva; conviene usarlas cuando aportan contraste o claridad, no en cada frase.'),
('Inversión formal','Con ciertos negativos al inicio, como Never o Rarely, se invierte auxiliar y sujeto: Never have I seen… Si no hay auxiliar, se usa do/does/did. Es una opción marcada, frecuente en estilos formales o enfáticos. No afecta al orden de cualquier frase negativa.')],
[('You did not answer my message.','No respondiste a mi mensaje.','Se presenta una afirmación que la otra persona va a corregir.'),('I did answer. I sent it to your old number.','Sí respondí. Lo envié a tu número antiguo.','Did + base refuerza y corrige la afirmación.'),('Oh, that explains it.','Ah, eso lo explica.','Se acepta la nueva explicación.'),('What I need is your new number.','Lo que necesito es tu nuevo número.','What I need coloca el foco en el número.')],
[('It was Sam who booked the room.','Fue Sam quien reservó la sala.','Se destaca a la persona responsable.'),('Rarely do we get a chance like this.','Rara vez tenemos una oportunidad así.','Rarely inicial provoca inversión con do.')],
['Why was the message not received?','¿Por qué no se recibió el mensaje?','It went to an old number','It was never sent','The phone was broken',1])
C('real-conditionals','Condiciones reales y posibles','a2',[
('Regularidades','If + presente, presente puede expresar una relación habitual: if I skip breakfast, I get hungry. When destaca algo esperado o repetido; if deja abierta la condición. La relación tiene que tener sentido: la forma gramatical no demuestra una regla científica.'),
('Un futuro posible','If + presente, will + base presenta una condición futura abierta y su consecuencia. La cláusula con if normalmente no lleva will para predecir ese futuro. El resultado también puede ser una petición, un modal o un imperativo: if you arrive early, call me.'),
('Tiempo y excepciones','After, before, until y as soon as suelen llevar presente al referirse al futuro. Unless significa a menos que y normalmente equivale a if not; evita duplicar la negación sin intención. Una condición inicial suele separarse con coma; después del resultado normalmente no.')],
[('What will we do if it rains?','¿Qué haremos si llueve?','Presente después de if para una condición futura.'),('We will eat inside.','Comeremos dentro.','Will presenta el resultado previsto.'),('And if the weather is good?','¿Y si hace buen tiempo?','El contexto permite omitir la segunda parte.'),('Then we can use the garden.','Entonces podemos usar el jardín.','Can expresa una opción que depende de la condición.')],
[('I will call you as soon as I arrive.','Te llamaré en cuanto llegue.','As soon as lleva presente con sentido futuro.'),('Unless you book, you may have to wait.','A menos que reserves, quizá tengas que esperar.','Unless introduce la condición negativa.')],
['Where will they eat if it rains?','¿Dónde comerán si llueve?','Inside','In the garden','At the station',1])
C('second-conditional','Imaginar otra situación','b1',[
('Distancia de la realidad','If + pasado, would + base imagina una situación presente o futura poco real, hipotética o menos probable desde la perspectiva de quien habla. El pasado marca distancia, no necesariamente tiempo pasado. La elección depende de cómo presentas la posibilidad.'),
('Consecuencias y alternativas','Would expresa un resultado imaginado; could, capacidad u opción; might, posibilidad. If I were you es una fórmula habitual de consejo. Were con otros sujetos es común en hipótesis formales; was aparece también en el uso, especialmente informal.'),
('Comparar dos perspectivas','If I have time, I will help deja abierta una posibilidad real. If I had time, I would help sugiere que ahora no lo tienes o lo ves poco probable. No se trata solo de cambiar una terminación: cambia la postura de quien habla.')],
[('Would you move abroad if you had the chance?','¿Te mudarías al extranjero si tuvieras la oportunidad?','Would y pasado presentan una hipótesis.'),('Maybe. I would need to find a job first.','Quizá. Primero tendría que encontrar trabajo.','Consecuencia imaginada, no un plan confirmado.'),('What would you do?','¿A qué te dedicarías?','Pregunta dentro de la misma situación hipotética.'),('If I spoke better English, I could teach art.','Si hablara mejor inglés, podría enseñar arte.','Could expresa una opción que la condición haría posible.')],
[('If I were you, I would ask for more time.','Si fuera tú, pediría más tiempo.','Consejo basado en ponerse en el lugar de otra persona.'),('If we had a car, we could visit them more often.','Si tuviéramos coche, podríamos visitarlos más a menudo.','La condición imaginada cambia las posibilidades actuales.')],
['Is the move already arranged?','¿La mudanza ya está organizada?','No, it is hypothetical','Yes, for tomorrow','Yes, the job is confirmed',1])
C('third-mixed','Imaginar un pasado diferente','b2',[
('Un resultado pasado alternativo','If + past perfect, would have + participio imagina otra condición y otro resultado pasados. Normalmente se entiende que la condición no ocurrió: if I had left earlier… No confundir would have con el pasado simple de una acción real.'),
('Pasado que afecta al presente','If + past perfect, would + base puede conectar una decisión pasada con un estado actual imaginado. Las referencias temporales como now explicitan la relación. La consecuencia no tiene que compartir el tiempo de la condición.'),
('Una característica y un hecho pasado','If + pasado, would have + participio puede combinar una característica presente o general con un resultado pasado. Antes de elegir formas, pregunta cuándo se sitúa cada parte. Could/might have permiten matizar capacidad o posibilidad en vez de un resultado seguro.')],
[('Why did we miss the train?','¿Por qué perdimos el tren?','Pregunta por un resultado real pasado.'),('We left home too late.','Salimos demasiado tarde de casa.','Se establece el hecho real.'),('If we had left earlier, we would have caught it.','Si hubiéramos salido antes, lo habríamos tomado.','Condición y consecuencia alternativas, ambas pasadas.'),('And we would be at the beach now.','Y ahora estaríamos en la playa.','Se conecta ese pasado alternativo con una consecuencia actual.')],
[('If I had accepted the job, I would live in Madrid now.','Si hubiera aceptado el trabajo, ahora viviría en Madrid.','Una decisión pasada cambia una situación presente.'),('If I were more organised, I would not have lost the receipt.','Si fuera más organizado, no habría perdido el recibo.','Una característica general se relaciona con un hecho pasado.')],
['What actually happened?','¿Qué ocurrió de verdad?','They missed the train','They caught the train','They arrived at the beach',0])
C('wishes','Deseos, arrepentimientos y molestias','b2',[
('Querer un presente distinto','Wish/if only + pasado expresa deseo de cambiar una situación presente. I wish I knew no significa que lo sabía antes: ahora no lo sé. Could expresa capacidad o posibilidad deseada. If only suele sonar más enfático.'),
('Lamentar el pasado','Wish + past perfect expresa arrepentimiento sobre un hecho anterior. I wish I had called implica que no llamé y ahora lo lamento. Para un futuro que consideras posible, hope suele ser apropiado: I hope the weather improves.'),
('Querer que algo cambie','Wish + would puede expresar deseo de cambio o molestia por una conducta repetida, normalmente con otro sujeto. No es el patrón general para desear capacidades propias: I wish I could sing. El contexto y el tono determinan si suena a queja.')],
[('I wish I lived closer to work.','Ojalá viviera más cerca del trabajo.','El pasado lived expresa un deseo sobre el presente.'),('Is the journey that long?','¿El trayecto es tan largo?','Se pide aclarar la situación real.'),('Yes. I wish I had checked the route before moving.','Sí. Ojalá hubiera comprobado la ruta antes de mudarme.','Had checked expresa arrepentimiento pasado.'),('I hope the new bus service helps.','Espero que ayude el nuevo servicio de autobús.','Hope presenta una posibilidad futura real.')],
[('I wish the neighbours would turn the music down.','Ojalá los vecinos bajaran la música.','Deseo de que cambie una conducta ajena.'),('I wish I could stay longer.','Ojalá pudiera quedarme más tiempo.','Could expresa una posibilidad deseada.')],
['What does the first speaker regret?','¿Qué lamenta la primera persona?','Not checking the route before moving','Taking a new job yesterday','Buying a bus ticket',2])
C('passive','Cuando importa lo que ocurre','b1',[
('Cambiar el foco','La pasiva presenta como sujeto a quien recibe una acción: the window was broken. Se construye con be en el tiempo necesario + participio. Solo ciertos verbos y sentidos con objeto permiten esta transformación; happen no se vuelve was happened.'),
('Tiempo y proceso','Is repaired describe una rutina o hecho general; is being repaired, una acción en curso; has been repaired, un resultado conectado con ahora; will be repaired, una previsión. El participio no cambia y la estructura auxiliar expresa tiempo y aspecto.'),
('Quién lo hizo','By introduce al agente cuando es relevante. Puede omitirse si se desconoce, es obvio o no importa para el mensaje. La activa suele ser más clara si el responsable es el foco. La pasiva no es automáticamente más formal o mejor.')],
[('Can I use the lift?','¿Puedo usar el ascensor?','Se pregunta por disponibilidad.'),('Not today. It is being repaired.','Hoy no. Lo están reparando.','Pasiva continua: la reparación está en proceso.'),('When will it be ready?','¿Cuándo estará listo?','Se pregunta por el resultado futuro.'),('The work should be finished by Friday.','El trabajo debería estar terminado para el viernes.','Modal + be + participio da una previsión.')],
[('The parcel was delivered yesterday.','El paquete fue entregado ayer.','La entrega importa más que identificar al repartidor.'),('This bridge was designed by a local architect.','Este puente fue diseñado por una arquitecta local.','By introduce una persona relevante.')],
['Why is the lift unavailable?','¿Por qué no está disponible el ascensor?','It is being repaired','It has been removed','It is only for staff',1])
C('services-reporting','Encargar servicios y atribuir información','b2',[
('Have/get something done','Have + objeto + participio suele indicar que encargas un servicio: I had my hair cut. No afirma que hiciste el trabajo personalmente. Get es frecuente en conversación. La misma estructura puede describir algo sufrido: had my phone stolen.'),
('Quién hace el trabajo','Have someone do y get someone to do nombran a quien actúa. No se confunden con have something done, donde el objeto recibe la acción. La situación aclara si se trata de una petición, un acuerdo o un encargo.'),
('Atribuir, no garantizar','It is said that… y is believed to… atribuyen una afirmación a fuentes no especificadas. To have + participio sitúa la acción atribuida antes del momento de informar. No convierten rumores en hechos: una comunicación responsable identifica la fuente si la conoce.')],
[('Did you fix the laptop yourself?','¿Arreglaste tú el portátil?','Se pregunta por quién realizó el trabajo.'),('No, I had it repaired at the shop.','No, hice que lo repararan en la tienda.','Had it repaired indica un servicio recibido.'),('Was it expensive?','¿Fue caro?','Se pregunta por el coste del servicio.'),('Less than I expected. They only replaced the battery.','Menos de lo que esperaba. Solo cambiaron la batería.','Activa cuando importa lo que hicieron los técnicos.')],
[('I got my brother to check the settings.','Conseguí que mi hermano revisara la configuración.','Get + persona + to + base.'),('The painting is believed to have been stolen.','Se cree que el cuadro fue robado.','Se atribuye una creencia sobre una acción anterior; no se prueba el robo.')],
['Who repaired the laptop?','¿Quién reparó el portátil?','Someone at the shop','The owner alone','The owner’s brother',1])
C('reported-speech','Contar lo que dijo otra persona','b1',[
('Cambiar la perspectiva','Al contar palabras ajenas, pronombres, posesivos y referencias temporales se ajustan a quien habla ahora. Say puede introducir el contenido; tell normalmente necesita destinatario: told me. No es una sustitución mecánica si el lugar o el día no han cambiado.'),
('Tiempos y vigencia','Tras un verbo de informe pasado es frecuente retroceder tiempos: is→was, have done→had done, will→would. No siempre es obligatorio si la información sigue vigente o se presenta como verdadera. El past perfect normalmente no retrocede más.'),
('Preguntas y peticiones','En preguntas indirectas se conserva el orden afirmativo: asked where I lived. Las de sí/no usan if/whether. Una petición puede contarse con asked someone to do; una orden negativa, told someone not to do. No se mantiene do auxiliar de la pregunta directa.')],
[('What did Mia say about the meeting?','¿Qué dijo Mia sobre la reunión?','Se pide transmitir información ajena.'),('She said it had been moved to Thursday.','Dijo que se había trasladado al jueves.','El cambio fue anterior a lo que dijo.'),('Did she ask us to bring anything?','¿Nos pidió que lleváramos algo?','Ask + persona + to + base transmite una petición.'),('Yes. She asked us to bring our notes.','Sí. Nos pidió que lleváramos nuestros apuntes.','Our ajusta el posesivo a quienes reciben el mensaje.')],
[('He told me that he was tired.','Me dijo que estaba cansado.','Tell incluye a la persona que recibe la información.'),('She asked where I worked.','Me preguntó dónde trabajaba.','Orden sujeto-verbo dentro de la pregunta transmitida.')],
['What should they bring?','¿Qué deben llevar?','Their notes','Their laptops','Their tickets',3])
C('indirect-questions','Preguntar con tacto y confirmar','a2',[
('Una pregunta dentro de otra','Could you tell me where the station is? contiene una introducción y una pregunta subordinada. Dentro se usa orden afirmativo: the station is, no is the station. La pregunta principal sí mantiene su forma interrogativa.'),
('If / whether','Si la pregunta original es de sí/no, añade if o whether: Do you know if it is open? No añadas do auxiliar dentro de esa cláusula. Wonder puede introducir una duda: I wonder whether she agrees, sin convertir toda la frase en pregunta directa.'),
('Confirmar lo entendido','So you mean…? y Do you mean…? comprueban una interpretación. Question tags como is it? o don’t you? buscan confirmación, pero la entonación cambia cuánto se duda. No hace falta usar una estructura larga si una pregunta breve ya es amable y clara.')],
[('Excuse me. Could you tell me where the station is?','Disculpa. ¿Podrías decirme dónde está la estación?','The station is mantiene orden afirmativo dentro de la pregunta.'),('It is just past the library.','Está justo después de la biblioteca.','Respuesta directa a la información solicitada.'),('Do you know if the ticket office is open?','¿Sabes si está abierta la taquilla?','If introduce una pregunta indirecta de sí/no.'),('Yes, it closes at six.','Sí, cierra a las seis.','Se responde y se aporta un detalle útil.')],
[('I wonder whether the price includes breakfast.','Me pregunto si el precio incluye el desayuno.','Whether introduce una duda sin inversión interna.'),('Do you mean the building on the left?','¿Te refieres al edificio de la izquierda?','Se comprueba una referencia antes de actuar.')],
['Where is the station?','¿Dónde está la estación?','Just past the library','Inside the library','Opposite the airport',1])
C('relatives','Identificar y añadir información','b1',[
('La información que identifica','Who suele referirse a personas; which, a cosas; that puede sustituirlos en relativas especificativas. La cláusula identifica de qué persona o cosa hablas. Si el relativo es objeto, puede omitirse: the book I bought. Si es sujeto, normalmente no.'),
('Un dato adicional','Las relativas explicativas añaden información sobre una referencia ya identificada y van entre comas. En ellas no se usa that ni se omite el relativo. Whose expresa posesión; where introduce lugares cuando tiene sentido de en/donde, no reemplaza todo which relacionado con sitios.'),
('Referirse a una idea','Which puede comentar una cláusula entera: He missed the bus, which made him late. Las relativas reducidas con -ing o participio describen grupos en contextos apropiados: people waiting outside, documents sent yesterday. El sujeto y el sentido deben quedar claros.')],
[('Who is the woman talking to Sam?','¿Quién es la mujer que habla con Sam?','Talking to Sam identifica a la mujer.'),('She is the architect who designed this building.','Es la arquitecta que diseñó este edificio.','Who es sujeto de designed y no se omite.'),('And is this the room that you booked?','¿Y esta es la sala que reservaste?','That es objeto de booked; puede omitirse.'),('Yes. It has the screen we need.','Sí. Tiene la pantalla que necesitamos.','Relativo objeto omitido: the screen that we need.')],
[('My sister, who lives in Leeds, is visiting.','Mi hermana, que vive en Leeds, está de visita.','Las comas presentan el lugar como información adicional.'),('The bus was late, which made us miss the start.','El autobús se retrasó, lo que hizo que nos perdiéramos el inicio.','Which se refiere a toda la situación anterior.')],
['What did the woman do?','¿Qué hizo la mujer?','She designed the building','She booked the room','She repaired the screen',1])
C('linkers','Conectar ideas con sentido','a1',[
('Añadir, contrastar, explicar','And añade; but contrasta; because introduce una razón; so introduce una consecuencia. La relación entre ideas importa más que usar muchos conectores. En inglés estándar no se suele enlazar una misma relación con because… so… como dos marcas duplicadas.'),
('Cláusula o grupo nominal','Although/even though van seguidos de cláusula; despite/in spite of llevan nombre o -ing. Because introduce cláusula; because of lleva grupo nominal. Despite the rain y although it rained expresan un contraste parecido con formas diferentes.'),
('Puntuación y organización','However y therefore suelen conectar enunciados y necesitan puntuación adecuada: punto o punto y coma antes, a menudo coma después. No basta una coma para unir dos oraciones independientes. Moreover, whereas y on the other hand sirven a relaciones específicas, no decoran el texto.')],
[('Would you like to walk home?','¿Te gustaría volver a casa caminando?','Se hace una propuesta.'),('Yes, but it is getting dark.','Sí, pero está oscureciendo.','But introduce una dificultad frente a la preferencia.'),('We can take the main road because it has lights.','Podemos ir por la avenida porque está iluminada.','Because introduce la razón para elegir la ruta.'),('Good idea. It is safer, so let us go that way.','Buena idea. Es más seguro, así que vayamos por ahí.','So presenta una consecuencia o decisión.')],
[('Although it was raining, we went out.','Aunque llovía, salimos.','Although va seguido de sujeto y verbo.'),('Despite the rain, we went out.','A pesar de la lluvia, salimos.','Despite va seguido de un nombre; no necesita of.')],
['Why do they choose the main road?','¿Por qué eligen la avenida?','It has lights','It is shorter','It has no cars',2])
C('social','Conocer gente y mantener la conversación','a1',[
('Empezar con contexto','Hi/hello abren una conversación; good morning/afternoon sitúan el saludo. Nice to meet you se usa al conocerse; nice to see you, al reencontrarse. Un saludo normalmente invita a una respuesta breve antes de pasar al tema.'),
('Interés y seguimiento','Una conversación crece con una respuesta y un detalle que la otra persona puede retomar. What about you? devuelve la pregunta. Where are you from? suele preguntar origen; where do you live? pregunta residencia. Pueden tener respuestas diferentes.'),
('Reaccionar y cerrar','Really?, That sounds nice y Me too reaccionan a lo que se acaba de decir. Sorry puede disculparse o pedir repetición según el tono. Well, I should go señala un cierre amable antes de despedirse; see you later no exige una cita exacta.')],
[('Hi, I am Leo. Is this your first class?','Hola, soy Leo. ¿Esta es tu primera clase?','Una presentación seguida de una pregunta relacionada con el lugar.'),('Yes. I am Mia. Nice to meet you.','Sí. Soy Mia. Encantada de conocerte.','Nice to meet you corresponde al primer encuentro.'),('Nice to meet you too. Where are you from?','Igualmente. ¿De dónde eres?','Too devuelve la cortesía; después se abre otro tema.'),('I am from Lima, but I live here now. What about you?','Soy de Lima, pero ahora vivo aquí. ¿Y tú?','Se distingue origen y residencia y se devuelve el turno.')],
[('That sounds interesting. How did you start?','Suena interesante. ¿Cómo empezaste?','Una reacción y una pregunta de seguimiento mantienen el intercambio.'),('Well, I should go. See you next week!','Bueno, tengo que irme. ¡Nos vemos la próxima semana!','Se prepara el cierre antes de despedirse.')],
['Where is Mia from?','¿De dónde es Mia?','Lima','London','Leeds',3])
C('services','Pedir, comprar y resolver problemas','a1',[
('Pedir algo concreto','I would like… es una forma cortés de pedir; can I have…? también es habitual. A/an o some dependen de lo que pides. Please ayuda, pero tono y contexto también cuentan. Want puede expresar deseo sin ser siempre la mejor apertura a una persona que atiende.'),
('Detalles que importan','For here or to take away?, What size? y cash or card? ofrecen alternativas. Responde al dato solicitado. How much pregunta precio o cantidad incontable; how many pregunta número de unidades. Confirmar tamaño, cantidad y precio reduce malentendidos.'),
('Explicar el problema','Describe primero el hecho: this is cold, it does not fit, I ordered tea. Después solicita una solución concreta con could I…? o could you…? Una reclamación clara distingue lo recibido de lo esperado sin atribuir intenciones a quien atiende.')],
[('Hi. Could I have a tea, please?','Hola. ¿Me das un té, por favor?','Una petición concreta y cortés.'),('Of course. For here or to take away?','Claro. ¿Para tomar aquí o para llevar?','Se pide elegir entre dos opciones.'),('For here. And a small sandwich, please.','Para tomar aquí. Y un bocadillo pequeño, por favor.','Respuesta breve ligada al contexto y una petición adicional.'),('Certainly. That is six pounds altogether.','Por supuesto. Son seis libras en total.','Altogether indica el total de la compra.')],
[('How much is this jacket?','¿Cuánto cuesta esta chaqueta?','How much pregunta por el precio.'),('I ordered tea, but this is coffee. Could you change it?','Pedí té, pero esto es café. ¿Podrías cambiarlo?','Se presenta el problema y una solución concreta.')],
['Will the customer stay in the café?','¿El cliente se quedará en la cafetería?','Yes','No, it is to take away','The conversation does not say',2])
C('describing-life','Hablar de tu vida cotidiana','a1',[
('Personas y relaciones','Live with, work with y spend time with describen relaciones distintas. Un retrato útil combina quién es alguien, qué hace y un detalle relevante. His/her se eligen por la persona poseedora, no por el género del objeto en español.'),
('Rutinas y lugares','El presente simple expresa actividades habituales; frequency words sitúan cuándo. Home no siempre lleva preposición tras go: go home. At home sitúa dónde estás. Work puede ser actividad incontable o verbo; a job es un puesto o tarea contable.'),
('Estados y necesidades','Be hungry/thirsty/tired expresa estados que en español pueden usar tener. Feel + adjetivo describe sensaciones. Have a headache expresa dolor de cabeza. Una descripción de síntomas comunica cómo te sientes, sin convertirla en un diagnóstico.')],
[('Who do you live with?','¿Con quién vives?','Live with pregunta por convivencia.'),('I live with my sister. She works at a hospital.','Vivo con mi hermana. Trabaja en un hospital.','She retoma sister y works concuerda con ella.'),('Do you see each other every day?','¿Os veis todos los días?','Each other expresa una relación recíproca.'),('Usually. We have dinner together after work.','Normalmente. Cenamos juntos después del trabajo.','Se añade una rutina concreta.')],
[('I go home at six and cook dinner.','Vuelvo a casa a las seis y preparo la cena.','Go home no necesita to.'),('I am tired and I have a headache.','Estoy cansado y me duele la cabeza.','Tired usa be; a headache usa have.')],
['When do they usually spend time together?','¿Cuándo suelen pasar tiempo juntos?','At dinner after work','At the hospital every morning','Only on Sundays',3])
C('narratives','Contar una experiencia que se entienda','b1',[
('Dar un punto de partida','Un relato orienta con quién, dónde y cuándo. El pasado simple hace avanzar los acontecimientos. El continuo da fondo o una acción en curso; el past perfect aclara algo anterior cuando el orden no está ya claro. No hace falta cambiar de tiempo en cada frase.'),
('Conectar causa y resultado','At first, then, after a while y eventually ayudan a seguir la secuencia. Suddenly marca un cambio inesperado. Eventually significa finalmente tras un proceso, no eventualmente como posibilidad. Los pronombres deben mantener referencias claras entre personajes.'),
('Seleccionar detalles','Un detalle sensorial o una reacción puede mostrar por qué importó una experiencia. Distingue lo que ocurrió, lo que creíste entonces y lo que aprendiste después. Un buen cierre resuelve la situación o explica su efecto, en vez de añadir una moraleja genérica.')],
[('How was your first day at work?','¿Qué tal tu primer día de trabajo?','Invita a contar una experiencia concreta.'),('At first, I was nervous. I could not find the office.','Al principio estaba nervioso. No encontraba la oficina.','Se establece el problema inicial.'),('What happened?','¿Qué pasó?','Una pregunta breve hace avanzar el relato.'),('A colleague saw me outside and showed me the way.','Un compañero me vio fuera y me indicó el camino.','Dos acciones simples resuelven la situación.')],
[('I was waiting for the bus when I noticed my wallet was missing.','Esperaba el autobús cuando noté que me faltaba la cartera.','Una acción de fondo y un acontecimiento que cambia la situación.'),('By the time I got home, my neighbour had found it.','Cuando llegué a casa, mi vecino ya la había encontrado.','El hallazgo ocurrió antes de mi llegada.')],
['Who helped on the first day?','¿Quién ayudó el primer día?','A colleague','A bus driver','A neighbour',3])
C('argument','Dar opiniones con razones y límites','b2',[
('Una postura que se pueda seguir','Una opinión clara presenta una idea central, una razón y un ejemplo pertinente. I think introduce una postura personal; evidence suggests atribuye una conclusión a pruebas. Un ejemplo aislado ilustra, pero no demuestra por sí solo una regla general.'),
('Reconocer otra perspectiva','Although, while y on the other hand permiten reconocer ventajas y límites. Concede un punto real antes de explicar por qué mantienes o ajustas tu postura. Una respuesta útil aborda la razón de la otra persona, no solo repite I disagree.'),
('Ajustar la fuerza','May, tend to, in some cases y to some extent evitan generalizaciones que no puedes sostener. Distingue hecho verificable, interpretación y recomendación. Un cierre puede indicar en qué condiciones tu propuesta funcionaría, en lugar de afirmar que sirve para todos.')],
[('Should the library stay open later?','¿Debería cerrar más tarde la biblioteca?','Una pregunta que admite posiciones razonadas.'),('I think so. People who work late could use it.','Creo que sí. Podrían usarla quienes trabajan hasta tarde.','Postura seguida de un beneficio concreto.'),('That would help, although staffing it would cost more.','Eso ayudaría, aunque el personal costaría más.','Se reconoce la ventaja y se introduce un límite.'),('Perhaps we could try one evening a week and review the demand.','Quizá podríamos probar una tarde por semana y evaluar la demanda.','Una propuesta limitada permite reunir evidencia.')],
[('This may reduce traffic, but the effect will depend on the route.','Esto puede reducir el tráfico, pero el efecto dependerá de la ruta.','La conclusión se formula con condiciones.'),('I agree to some extent; however, the data only cover one month.','Estoy de acuerdo en parte; sin embargo, los datos solo abarcan un mes.','Se reconoce un acuerdo parcial y un límite de la evidencia.')],
['What compromise is proposed?','¿Qué acuerdo intermedio se propone?','Try one late evening each week','Open all night every day','Close the library',3])
C('negotiation','Llegar a un acuerdo','b1',[
('Propuestas y preferencias','Shall we…?, How about + -ing? y We could… abren opciones. Would you rather + base? compara preferencias; prefer puede llevar nombre, -ing o to + base según el patrón. Una sugerencia no equivale a una decisión confirmada.'),
('Mostrar acuerdo parcial','That could work, but… reconoce una idea antes de plantear una dificultad. I see your point muestra comprensión sin prometer acuerdo. Las alternativas ganan claridad cuando explican qué necesidad resuelven: tiempo, coste, accesibilidad o comodidad.'),
('Cerrar con datos claros','Una negociación termina confirmando quién hace qué, cuándo y bajo qué condición. So we have agreed… resume el acuerdo. Si un punto sigue abierto, nómbralo. Un silencio o una respuesta ambigua no siempre significa aceptación.')],
[('Shall we meet at six?','¿Quedamos a las seis?','Shall we propone una acción conjunta.'),('I finish work at six. Could we make it half past?','Termino de trabajar a las seis. ¿Podríamos quedar a y media?','Se explica un límite y se propone otra hora.'),('That works for me. At the café near the station?','Me va bien. ¿En la cafetería cerca de la estación?','Se acepta la hora y se concreta el lugar.'),('Perfect. I will see you there at six thirty.','Perfecto. Te veo allí a las seis y media.','Se confirma el acuerdo para evitar confusión.')],
[('How about taking the earlier train?','¿Qué tal si tomamos el tren anterior?','How about va seguido de -ing.'),('So you will book the room, and I will bring the materials.','Entonces tú reservas la sala y yo llevo los materiales.','El cierre asigna responsabilidades concretas.')],
['What time do they agree on?','¿A qué hora quedan?','Six thirty','Six','Seven thirty',3])
C('messages','Mensajes y correos útiles','a1',[
('Lo esencial de un mensaje','Un mensaje breve deja claro quién escribe, qué ocurre y si espera una respuesta. Las contracciones son naturales en mensajes personales. No omitas datos necesarios como hora o lugar. Puedes ser breve sin convertir cada frase en una abreviatura difícil de entender.'),
('Elegir el registro','Hi + nombre funciona en muchos intercambios cercanos y profesionales cotidianos. Dear + nombre puede ser más formal. Un mensaje formal tiende a explicitar el motivo y la petición. El registro depende de relación, propósito y cultura, no solo del tipo de saludo.'),
('Pedir una acción y cerrar','Could you confirm…?, Please let me know… y I look forward to hearing from you indican qué respuesta esperas. Look forward to lleva -ing porque to es preposición. Incluye plazos reales si hacen falta; evita pedidos vagos como answer soon sin contexto.')],
[('Hi Mia, I am running ten minutes late.','Hola, Mia. Voy con diez minutos de retraso.','Running late describe un retraso respecto al plan.'),('No problem. I am still on the bus.','Sin problema. Todavía estoy en el autobús.','Se comunica el estado actual relevante.'),('Shall we meet outside the cinema?','¿Quedamos fuera del cine?','Se concreta un punto de encuentro.'),('Yes. Send me a message when you arrive.','Sí. Envíame un mensaje cuando llegues.','Petición clara con una condición temporal.')],
[('Could you confirm whether breakfast is included?','¿Podría confirmar si está incluido el desayuno?','Petición concreta en un correo de consulta.'),('I look forward to hearing from you.','Quedo a la espera de su respuesta.','Hearing va en -ing tras la preposición to.')],
['What should happen on arrival?','¿Qué debe ocurrir al llegar?','Send a message','Buy new tickets','Take another bus',3])
C('genres','Leer y escribir según el propósito','b2',[
('Párrafos que hacen un trabajo','Un párrafo desarrolla una idea central con apoyo relevante. El orden depende del propósito: un ensayo razona una postura; una propuesta recomienda una acción; un informe organiza hallazgos. Un conector no arregla una relación lógica que falta.'),
('Adaptar el texto a su lector','Un informe puede usar secciones y recomendaciones; una reseña combina descripción y valoración; un artículo puede buscar interés con un inicio concreto. La extensión y el formato dependen de la tarea. Cumplir una plantilla sin responder al destinatario no garantiza un buen texto.'),
('Revisar contenido antes de pulir','Primero comprueba que respondas a la tarea, que las afirmaciones tengan apoyo y que no se contradigan. Después revisa conexión, referencias, vocabulario, formas verbales y puntuación. Una palabra más rara no mejora una frase si cambia el sentido o el registro.')],
[('Who is this report for?','¿Para quién es este informe?','El destinatario orienta qué información incluir.'),('The manager. She needs to decide whether to extend the opening hours.','Para la gerente. Tiene que decidir si ampliar el horario.','Se define el propósito práctico del texto.'),('Then the survey results should come before the recommendation.','Entonces los resultados de la encuesta deberían ir antes de la recomendación.','La evidencia prepara la decisión propuesta.'),('Agreed. I will also explain the limits of the sample.','De acuerdo. También explicaré los límites de la muestra.','Se evita presentar evidencia limitada como una certeza universal.')],
[('The main drawback is the cost of additional staff.','El principal inconveniente es el coste de más personal.','Una evaluación útil nombra un límite específico.'),('We recommend a trial period before making a permanent change.','Recomendamos un periodo de prueba antes de un cambio permanente.','Recomendación concreta y proporcionada a la evidencia.')],
['What decision will the report support?','¿Qué decisión apoyará el informe?','Whether to extend opening hours','Whether to change the manager','Which book to publish',1])
C('mediation','Aclarar, resumir y transmitir','b1',[
('Llevar lo esencial a otra persona','Mediar puede ser resumir instrucciones, explicar un aviso o transmitir un acuerdo. Selecciona lo que el destinatario necesita y conserva condiciones, fechas y excepciones importantes. Resumir no consiste en cambiar todas las palabras por sinónimos.'),
('Explicar con otras palabras','In other words, what this means is y the main point is introducen aclaraciones. Puedes dividir una frase compleja en dos más sencillas. Mantén el grado de certeza: may no se vuelve will solo por simplificar el mensaje.'),
('Comprobar y corregir','So, just to check… confirma lo entendido. Si falta información, dilo y pregunta; no rellenes huecos con suposiciones. Al transmitir palabras ajenas, distingue lo que la fuente dijo de tu interpretación o recomendación.')],
[('I do not understand this notice. Is the entrance closed?','No entiendo este aviso. ¿Está cerrada la entrada?','Se identifica una duda concreta.'),('The main entrance is closed, but the side door is open.','La entrada principal está cerrada, pero la puerta lateral está abierta.','Se conserva la distinción crucial del aviso.'),('So we can still go in?','Entonces, ¿todavía podemos entrar?','Se comprueba una conclusión.'),('Yes, until five. After that, the whole building closes.','Sí, hasta las cinco. Después cierra todo el edificio.','Se añade una condición que no debe perderse al resumir.')],
[('In other words, we need to book before Friday.','En otras palabras, tenemos que reservar antes del viernes.','La reformulación conserva la acción y el plazo.'),('The message says the date may change; it does not confirm a new one.','El mensaje dice que la fecha puede cambiar; no confirma una nueva.','Se distingue posibilidad de confirmación.')],
['How can they enter before five?','¿Cómo pueden entrar antes de las cinco?','Through the side door','Through the main entrance','They cannot enter at all',1])
C('listening','Entender el mensaje y sus pistas','b1',[
('Intención y situación','Entender una conversación incluye quién habla, qué necesita y cómo responde la otra persona. Antes de fijarte en un dato, identifica si se propone, se rechaza, se corrige o se confirma algo. No necesitas reconocer cada palabra para seguir la idea principal.'),
('Detalles que se corrigen','Una cifra o lugar puede aparecer y después descartarse: not Tuesday, Thursday. La primera palabra conocida no es siempre la respuesta. But, actually y instead suelen anunciar un cambio. Relaciona cada dato con la intención final, no con su mera presencia.'),
('Inferir con evidencia','Tono, contexto y elección de palabras ayudan a inferir actitudes, pero no permiten leer pensamientos. Diferencia información explícita e interpretación. En una prueba, busca qué parte del audio apoya la respuesta y reconoce cuando una opción añade algo que no se dijo.')],
[('Shall I book the table for Tuesday?','¿Reservo la mesa para el martes?','Se propone una fecha, aún no confirmada.'),('Actually, Thursday would be better.','En realidad, el jueves sería mejor.','Actually corrige la propuesta anterior.'),('At seven, as usual?','¿A las siete, como siempre?','Se propone una hora apoyada en una rutina.'),('Could we make it seven thirty? My train arrives at seven.','¿Podría ser a las siete y media? Mi tren llega a las siete.','Se corrige la hora y se da una razón.')],
[('I thought it was free, but there is a small charge.','Creía que era gratis, pero hay una pequeña tarifa.','La información después de but corrige la creencia inicial.'),('It is quite a long walk, so perhaps we should take the bus.','Es un paseo bastante largo, así que quizá deberíamos tomar el autobús.','La distancia justifica una sugerencia; aún no confirma la decisión.')],
['What day is preferred?','¿Qué día se prefiere?','Thursday','Tuesday','Wednesday',1])
C('pronunciation','Sonidos, ritmo y habla conectada','a1',[
('Sonido no equivale a letra','Las letras inglesas no tienen una única pronunciación. El alfabeto fonético permite representar sonidos; pares como ship/sheep contrastan categorías, no solo duración. El panel de 44 sonidos sigue un modelo didáctico británico frecuente: otros acentos tienen inventarios y realizaciones diferentes.'),
('Acento de palabra y frase','Una sílaba suele destacar dentro de una palabra. En una frase, las palabras informativas suelen recibir más relieve, mientras palabras funcionales pueden reducirse. El acento cambia con el contraste que se quiere comunicar. No todas las palabras deben durar o sonar igual.'),
('Unir sin perder el sentido','En habla continua los sonidos pueden enlazarse, reducirse o cambiar según el entorno. La entonación organiza intención y turnos, pero no hay una melodía única para todas las preguntas. La meta es resultar comprensible y comprender acentos, no borrar obligatoriamente tu identidad.')],
[('Did you say ship or sheep?','¿Dijiste ship o sheep?','Se pide confirmar un contraste de vocal.'),('Sheep. The animal.','Sheep. El animal.','El contexto semántico ayuda a identificar la palabra.'),('Oh, I see. And where is the stress in hotel?','Ah, entiendo. ¿Y dónde está el acento en hotel?','Stress aquí significa acento de palabra.'),('On the second syllable: hotel.','En la segunda sílaba: hotel.','La sílaba destacada es la segunda.')],
[('I wanted the blue one, not the green one.','Quería el azul, no el verde.','Blue y green reciben contraste porque distinguen las opciones.'),('Could you say that again, please?','¿Podrías repetirlo, por favor?','Una petición de repetición sirve cuando un sonido o enlace no quedó claro.')],
['Which word did the second speaker say?','¿Qué palabra dijo la segunda persona?','Sheep','Ship','Shop',1])
C('spelling','Escritura, apóstrofos y puntuación','a1',[
('Letras y mayúsculas','I se escribe con mayúscula; también nombres propios, días, meses, idiomas y nacionalidades. El nombre de una letra no es su sonido dentro de una palabra. Al deletrear, confirma letras que puedan confundirse y divide datos largos en grupos.'),
('Apóstrofo y contracciones','It’s suele ser it is o it has; its es posesivo sin apóstrofo. You’re es you are; your acompaña un nombre. El apóstrofo de posesión no sirve para formar plurales normales. Contracciones como don’t son habituales en conversación y muchos textos informales.'),
('Límites de frase','El punto cierra un enunciado; la coma separa elementos o cláusulas en contextos concretos. No une por sí sola dos oraciones independientes. Revisa sujeto y verbo, referencias y signos. El inglés usa el signo de interrogación al final, sin el signo inicial español.')],
[('Could you spell your surname, please?','¿Podrías deletrear tu apellido, por favor?','Spell pide las letras, no una traducción.'),('Of course. It is Green: G, R, E, E, N.','Claro. Es Green: G, R, E, E, N.','El apellido se confirma con sus letras.'),('Thank you. Is your appointment on Monday?','Gracias. ¿Tu cita es el lunes?','Monday lleva mayúscula.'),('Yes, at ten.','Sí, a las diez.','Una respuesta breve puede omitir lo conocido.')],
[('It’s raining, and the dog is in its bed.','Está lloviendo y el perro está en su cama.','It’s significa it is; its indica posesión.'),('You’re welcome to bring your sister.','Puedes traer a tu hermana.','You’re equivale a you are; your acompaña sister.')],
['When is the appointment?','¿Cuándo es la cita?','Monday at ten','Monday at nine','Tuesday at ten',3])
C('work','Colaborar y explicar tu experiencia','b1',[
('Experiencia con ejemplos','En entrevistas y presentaciones, una capacidad gana claridad con una situación, tu acción y su resultado. El presente perfect puede resumir experiencia; el pasado simple describe un caso terminado. No atribuyas a toda la empresa un resultado que no puedes sostener.'),
('Acuerdos de trabajo','Una petición útil identifica la tarea, el plazo y el motivo cuando hace falta. Could you…? suaviza, pero no sustituye los datos. By Friday significa como fecha límite; until Friday expresa continuidad hasta ese momento. Son relaciones temporales distintas.'),
('Progreso y dificultades','I have finished… comunica un resultado; I am working on… indica proceso; I am waiting for… identifica dependencia. Explicar un problema junto con una opción permite decidir. Un correo de seguimiento puede confirmar responsables y próximos pasos.')],
[('How is the report going?','¿Cómo va el informe?','Una pregunta de seguimiento sobre progreso.'),('I have finished the first section, but I am waiting for the figures.','He terminado la primera sección, pero espero las cifras.','Se distingue resultado conseguido y dependencia actual.'),('Can you send me what you have by three?','¿Puedes enviarme lo que tienes antes de las tres como máximo?','By three fija un límite de entrega.'),('Yes. I will mark the parts that still need checking.','Sí. Marcaré las partes que aún necesitan revisión.','Se confirma la acción y se explica el estado incompleto.')],
[('In my last role, I trained two new colleagues.','En mi anterior puesto formé a dos compañeros nuevos.','Un ejemplo concreto respalda la experiencia.'),('I can finish this today if the figures arrive before noon.','Puedo terminarlo hoy si las cifras llegan antes del mediodía.','Se comunica una condición necesaria para cumplir el plazo.')],
['What is the report writer waiting for?','¿Qué espera quien escribe el informe?','The figures','A new computer','A meeting room',1])
C('reviews','Comparar opciones y recomendar','b1',[
('Qué evalúas y para quién','Una reseña identifica el objeto o experiencia y selecciona criterios relevantes: precio, comodidad, claridad o accesibilidad. Distingue descripción y valoración. Una recomendación útil dice para quién encaja, en lugar de presentar una preferencia como universal.'),
('Apoyar una valoración','Adjetivos como excellent o disappointing ganan sentido con detalles. Comparativos y contrastes muestran ventajas y límites. Bored describe una reacción; boring describe lo que la produce. No es necesario revelar toda una historia para evaluar su ritmo o personajes.'),
('Recomendar con condiciones','Worth + nombre/-ing expresa que algo merece la pena. Recommend + -ing o recommend that… son patrones habituales; no uses recommend you to como equivalente general de te recomiendo que. La recomendación puede incluir una condición: si priorizas silencio, si viajas con niños, si ya conoces el tema.')],
[('Would you recommend the hotel?','¿Recomendarías el hotel?','Se solicita una evaluación práctica.'),('For a short stay, yes. The room was small but very clean.','Para una estancia corta, sí. La habitación era pequeña, pero muy limpia.','Se define el uso y se contrastan dos aspectos.'),('Was it noisy?','¿Había mucho ruido?','Se pregunta por un criterio importante para decidir.'),('A little. I would ask for a room away from the road.','Un poco. Pediría una habitación lejos de la carretera.','Se ofrece una solución concreta al límite observado.')],
[('The museum is worth visiting, especially if you enjoy local history.','Vale la pena visitar el museo, sobre todo si te gusta la historia local.','Worth lleva -ing y la recomendación identifica a su público.'),('I recommend booking in advance because the rooms fill up quickly.','Recomiendo reservar con antelación porque las habitaciones se llenan rápido.','Recommend va seguido de -ing y una razón específica.')],
['What is the main drawback mentioned?','¿Qué inconveniente se menciona?','Some noise from the road','Dirty rooms','Unhelpful staff',3])
